parameters.jsCode:
// Datos de tu proyecto. Es el único nodo que hay que editar después de importar.
// La anon key de Supabase es pública (la usa también la app): no es un secreto.
// La clave de Gemini NO va acá: va en la credencial "Gemini" de n8n.
const config = {
  supabaseUrl: 'https://TU-PROYECTO.supabase.co',
  supabaseAnonKey: 'TU-ANON-KEY',
  model: 'gemini-flash-latest',
  embeddingModel: 'gemini-embedding-001',
};
return { json: { ...$json, config } };

// Junta en un solo objeto quién es la persona (validado por Supabase) y qué mandó.
const req = $('Entrada desde la app').item.json;
const body = req.body ?? {};
const user = $json.body ? JSON.parse($json.body) : {};
const kind = body.kind;
if (!['audio', 'image', 'text', 'link'].includes(kind)) {
  throw new Error('kind tiene que ser audio, image, text o link');
}
const tz = body.tz || 'America/Argentina/Buenos_Aires';
return {
  json: {
    user_id: user.id,
    kind,
    text: body.text ?? '',
    url: body.url ?? null,
    data: body.data ?? null,
    mimeType: body.mimeType ?? null,
    photo_path: body.photoPath ?? null,
    tz,
    today: body.today || $now.setZone(tz).toISODate(),
  },
};

// Saca de la página lo que sirve para entenderla: título, descripción y algo de texto.
const pedido = $('Normalizar').item.json;
const html = typeof $json.body === 'string' ? $json.body : '';
const meta = (name) => {
  const re = new RegExp(`<meta[^>]+(?:property|name)=["']${name}["'][^>]*content=["']([^"']*)["']`, 'i');
  const re2 = new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*(?:property|name)=["']${name}["']`, 'i');
  return (html.match(re) || html.match(re2) || [])[1] || '';
};
const title = meta('og:title') || (html.match(/<title[^>]*>([^<]*)<\/title>/i) || [])[1] || '';
const description = meta('og:description') || meta('description');
const texto = html
  .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);
return {
  json: {
    ...pedido,
    page: { ok: $json.statusCode >= 200 && $json.statusCode < 400, title, description, image: meta('og:image'), text: texto },
  },
};

// Arma el pedido a Gemini: un audio, una foto, un texto o un enlace ya leído.
const p = $json;
const { model } = $('Configuración').item.json.config;

const instrucciones = `Eres el asistente de Floppy, una app que convierte lo que la persona dice, fotografía o comparte en TAREAS, GASTOS y GUARDADOS.
Hoy es ${p.today} (zona horaria ${p.tz}). Moneda por defecto: pesos argentinos (ARS).

Qué va en cada lista:
- tasks: algo que la persona tiene que hacer. Título corto en infinitivo ("Llamar al contador"). Si menciona un día ("mañana", "el jueves", "el 15"), due_date en AAAA-MM-DD; si no, null.
- expenses: plata que ya se gastó. amount es un número sin símbolos ni separadores de miles. category es una de: Supermercado, Comida, Transporte, Hogar, Servicios, Salud, Mascotas, Ropa, Ocio, Otros.
- saved: algo para recordar o volver a ver que no es una tarea ni un gasto: una idea, una receta, un dato, un lugar, un enlace, una foto que interesa.
  kind es "note" (texto o audio), "link" (enlace) o "photo" (imagen que no es un ticket).
  title corto y claro; summary de una o dos frases; tags: entre 1 y 4 etiquetas en minúscula ("receta", "viaje", "trabajo").

Reglas:
- Una misma entrada puede dejar cosas en varias listas ("mañana llamar al contador y gasté 12000 en el súper" = 1 tarea + 1 gasto).
- La foto de un ticket o factura es UN gasto con el comercio, el total, la fecha del ticket y los ítems que se lean. No es un guardado.
- La foto de un papel con anotaciones son tareas o notas, según lo que diga.
- Un enlace siempre deja un guardado kind "link", resumiendo de qué trata la página.
- No inventes nada que no esté. Si una lista no tiene nada, devuélvela vacía.
- transcript: lo que dijo la persona (audio) o lo que se lee (imagen), resumido si es largo.
- summary: una frase corta, en español, de lo que hiciste ("Agendé 1 tarea y anoté 1 gasto").`;

const parts = [{ text: instrucciones }];
if (p.kind === 'text') {
  parts.push({ text: `Texto de la persona: ${p.text}` });
} else if (p.kind === 'link') {
  const pg = p.page ?? {};
  parts.push({
    text: `Enlace compartido: ${p.url}\nComentario de la persona: ${p.text || '(ninguno)'}\n` +
      (pg.ok ? `Título: ${pg.title}\nDescripción: ${pg.description}\nTexto de la página: ${pg.text}` : 'No se pudo leer la página: resume a partir del enlace.'),
  });
} else {
  if (!p.data || !p.mimeType) throw new Error('Faltan data (base64) o mimeType');
  parts.push({ inline_data: { mime_type: p.mimeType, data: p.data } });
  if (p.text) parts.push({ text: `Comentario de la persona: ${p.text}` });
}

const S = (extra = {}) => ({ type: 'STRING', ...extra });
const schema = {
  type: 'OBJECT',
  properties: {
    transcript: S(),
    summary: S(),
    tasks: { type: 'ARRAY', items: { type: 'OBJECT', properties: { title: S(), due_date: S({ nullable: true }), notes: S({ nullable: true }) }, required: ['title'] } },
    expenses: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          merchant: S({ nullable: true }), amount: { type: 'NUMBER' }, currency: S(), category: S(), spent_on: S({ nullable: true }),
          items: { type: 'ARRAY', nullable: true, items: { type: 'OBJECT', properties: { name: S(), amount: { type: 'NUMBER', nullable: true } } } },
        },
        required: ['amount', 'category'],
      },
    },
    saved: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: { kind: S({ enum: ['note', 'link', 'photo'] }), title: S(), summary: S({ nullable: true }), content: S({ nullable: true }), tags: { type: 'ARRAY', items: S() } },
        required: ['kind', 'title'],
      },
    },
  },
  required: ['transcript', 'summary', 'tasks', 'expenses', 'saved'],
};

return {
  json: {
    model,
    request: { contents: [{ role: 'user', parts }], generationConfig: { responseMimeType: 'application/json', responseSchema: schema, temperature: 0.2 } },
  },
};

// Lee la respuesta de Gemini, la limpia y prepara los textos para los embeddings.
// Si era un enlace, el pedido viene de "Extraer de la página"; si no, de "Normalizar".
const p = $('Extraer de la página').isExecuted ? $('Extraer de la página').item.json : $('Normalizar').item.json;
const { embeddingModel } = $('Configuración').item.json.config;
const raw = $json.candidates?.[0]?.content?.parts?.map((x) => x.text ?? '').join('') ?? '';
let d;
try { d = JSON.parse(raw); } catch { throw new Error('Gemini no devolvió un JSON válido: ' + raw.slice(0, 200)); }

const fecha = (v) => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null);
const CATS = ['Supermercado', 'Comida', 'Transporte', 'Hogar', 'Servicios', 'Salud', 'Mascotas', 'Ropa', 'Ocio', 'Otros'];

const tasks = (d.tasks ?? []).filter((t) => t.title?.trim())
  .map((t) => ({ title: t.title.trim(), due_date: fecha(t.due_date), notes: t.notes || null }));

const expenses = (d.expenses ?? []).filter((g) => Number.isFinite(Number(g.amount)) && Number(g.amount) >= 0)
  .map((g) => ({
    merchant: g.merchant || null,
    amount: Number(g.amount),
    currency: (g.currency || 'ARS').toUpperCase().slice(0, 3),
    category: CATS.includes(g.category) ? g.category : 'Otros',
    spent_on: fecha(g.spent_on),
    items: g.items?.length ? g.items : null,
    // La foto del ticket queda con el gasto.
    photo_path: p.kind === 'image' ? p.photo_path : null,
  }));

const saved = (d.saved ?? []).filter((s) => s.title?.trim())
  .map((s) => ({
    kind: ['note', 'link', 'photo'].includes(s.kind) ? s.kind : 'note',
    title: s.title.trim(),
    summary: s.summary || null,
    content: s.content || null,
    url: p.kind === 'link' ? p.url : null,
    photo_path: s.kind === 'photo' ? p.photo_path : null,
    tags: (s.tags ?? []).map((t) => String(t).toLowerCase().trim()).filter(Boolean).slice(0, 4),
  }));
// Un enlace siempre queda guardado, aunque el modelo no lo haya puesto.
if (p.kind === 'link' && !saved.some((s) => s.kind === 'link')) {
  saved.push({ kind: 'link', title: p.page?.title || p.url, summary: p.page?.description || null, content: null, url: p.url, photo_path: null, tags: [] });
}

// Texto que representa cada cosa para buscarla después por significado.
const textos = [
  ...tasks.map((t) => `Tarea: ${t.title}. ${t.notes ?? ''} ${t.due_date ?? ''}`),
  ...expenses.map((g) => `Gasto: ${g.merchant ?? ''} ${g.category} ${g.amount} ${g.currency}. ${(g.items ?? []).map((i) => i.name).join(', ')}`),
  ...saved.map((s) => `${s.title}. ${s.summary ?? ''} ${s.tags.join(' ')} ${s.url ?? ''}`),
];
const paraEmbeddings = textos.length ? textos : ['(vacío)'];

return {
  json: {
    user_id: p.user_id,
    source: p.kind,
    transcript: d.transcript ?? '',
    summary: d.summary ?? '',
    tasks,
    expenses,
    saved,
    embeddingRequest: {
      requests: paraEmbeddings.map((text) => ({
        model: `models/${embeddingModel}`,
        content: { parts: [{ text }] },
        taskType: 'RETRIEVAL_DOCUMENT',
        outputDimensionality: 768,
      })),
    },
  },
};

// Le pone a cada tarea, gasto y guardado su vector, en el mismo orden en que se pidieron.
const d = $('Leer respuesta').item.json;
const vecs = ($json.embeddings ?? []).map((e) => `[${e.values.join(',')}]`);
let i = 0;
const con = (lista) => lista.map((x) => ({ ...x, embedding: vecs[i++] ?? null }));
return {
  json: {
    user_id: d.user_id,
    source: d.source,
    transcript: d.transcript,
    summary: d.summary,
    tasks: con(d.tasks),
    expenses: con(d.expenses),
    saved: con(d.saved),
  },
};

parameters.query:
with t as (
  insert into tasks (user_id, title, due_date, notes, source, embedding)
  select $4::uuid, title, due_date, notes, $5, embedding::vector
  from json_to_recordset($1::json) as x(title text, due_date date, notes text, embedding text)
  returning id
), e as (
  insert into expenses (user_id, merchant, amount, currency, category, spent_on, items, photo_path, source, embedding)
  select $4::uuid, merchant, amount, currency, category, coalesce(spent_on, current_date), items, photo_path, $5, embedding::vector
  from json_to_recordset($2::json) as x(merchant text, amount numeric, currency text, category text, spent_on date, items jsonb, photo_path text, embedding text)
  returning id
), s as (
  insert into saved (user_id, kind, title, summary, content, url, photo_path, tags, source, embedding)
  select $4::uuid, kind, title, summary, content, url, photo_path, coalesce(tags, '{}'), $5, embedding::vector
  from json_to_recordset($3::json) as x(kind text, title text, summary text, content text, url text, photo_path text, tags text[], embedding text)
  returning id
)
select (select count(*) from t) as tasks, (select count(*) from e) as expenses, (select count(*) from s) as saved;
